// SPDX-License-Identifier: CC0-1.0
#include FENWICK2D_LIBRARY
#include <array>
#include <chrono>
#include <cstdio>
#include <string>
#include <sys/resource.h>
struct Point { int x,y;std::int64_t w; };
struct Query { int l,d,r,u; };
static std::uint64_t random_state=0x5c3940ac32ULL;
static std::uint64_t rng(){random_state^=random_state<<7;random_state^=random_state>>9;return random_state;}
using Clock=std::chrono::steady_clock;
static std::int64_t elapsed(Clock::time_point t){return std::chrono::duration_cast<std::chrono::nanoseconds>(Clock::now()-t).count();}
int main(int argc,char**argv){
 const std::string name=argc>1?argv[1]:"compressed";
 int n=200000,m=200000,updates=40000,queries=30000;
 if(name=="small"){n=32;m=32;updates=20000;queries=30000;}
 else if(name=="dense"){n=2048;m=2048;updates=20000;queries=20000;}
 else if(name=="moderate"){n=4096;m=4096;updates=20000;queries=20000;}
 else if(name=="tall"){n=1000001;m=65;updates=5000;queries=10000;}
 else if(name=="wide"){n=1000000000;m=1000000000;updates=1500;queries=4000;}
 else if(name=="threshold"){n=1;m=4096;updates=300;queries=30000;}
 std::vector<Point> points;std::vector<Query> qs;
 for(int k=0;k<updates;++k)points.push_back({static_cast<int>(rng()%n),static_cast<int>(rng()%m),static_cast<std::int64_t>(rng()%1000)-400});
 for(int k=0;k<queries;++k){int l=rng()%(static_cast<std::uint64_t>(n)+1),r=rng()%(static_cast<std::uint64_t>(n)+1),d=rng()%(static_cast<std::uint64_t>(m)+1),u=rng()%(static_cast<std::uint64_t>(m)+1);if(l>r)std::swap(l,r);if(d>u)std::swap(d,u);qs.push_back({l,d,r,u});}
 DynamicFenwickTree2D<std::int64_t> bit(n,m);auto begin=Clock::now();for(const auto&p:points)bit.add(p.x,p.y,p.w);auto add_ns=elapsed(begin);
 std::int64_t checksum=0;const auto nodes=bit.stored_nodes();
 begin=Clock::now();for(const auto&q:qs)checksum+=bit.sum(q.l,q.d,q.r,q.u);auto rectangle_ns=elapsed(begin);
 begin=Clock::now();for(const auto&q:qs)checksum+=bit.sum(q.r,q.u);auto prefix_ns=elapsed(begin);
 begin=Clock::now();for(int k=0;k<2000;++k){const auto&p=points[k%points.size()];checksum+=bit.get(p.x,p.y);}auto get_ns=elapsed(begin);
 if(nodes!=bit.stored_nodes())return 2;
 begin=Clock::now();for(int k=0;k<2000;++k){const auto&p=points[k%points.size()];bit.set(p.x,p.y,k-1000);}auto set_ns=elapsed(begin);
 std::int64_t copy_ns;begin=Clock::now();{auto clone=bit;copy_ns=elapsed(begin);checksum+=clone.sum_all();}
 begin=Clock::now();bit.clear();for(const auto&p:points)bit.add(p.x,p.y,p.w);auto refill_ns=elapsed(begin);checksum+=bit.sum_all();
 struct rusage usage{};getrusage(RUSAGE_SELF,&usage);
 std::printf("{\"case\":\"%s\",\"add_ns\":%jd,\"rectangle_ns\":%jd,\"prefix_ns\":%jd,\"get_ns\":%jd,\"set_ns\":%jd,\"copy_ns\":%jd,\"refill_ns\":%jd,\"nodes\":%zu,\"checksum\":%jd,\"peak_rss_kib\":%jd}\n",name.c_str(),static_cast<std::intmax_t>(add_ns),static_cast<std::intmax_t>(rectangle_ns),static_cast<std::intmax_t>(prefix_ns),static_cast<std::intmax_t>(get_ns),static_cast<std::intmax_t>(set_ns),static_cast<std::intmax_t>(copy_ns),static_cast<std::intmax_t>(refill_ns),nodes,static_cast<std::intmax_t>(checksum),static_cast<std::intmax_t>(usage.ru_maxrss));
}

